interface MockResponse<T> {
    data: T;
    status: number;
}

class MockHttpClient {
    private responses: Map<string, MockResponse<unknown>> = new Map();
    private errorResponses: Map<string, Error> = new Map();

    private getUrlKey(url: string): string {
        const withoutQuery = url.split("?")[0];
        try {
            return decodeURIComponent(withoutQuery);
        } catch {
            return withoutQuery;
        }
    }

    private getResponse(url: string): MockResponse<unknown> | undefined {
        return this.responses.get(url) || this.responses.get(this.getUrlKey(url));
    }

    private getError(url: string): Error | undefined {
        return this.errorResponses.get(url) || this.errorResponses.get(this.getUrlKey(url));
    }

    public setResponse(url: string, response: MockResponse<unknown>): void {
        this.responses.set(url, response);
    }

    public setError(url: string, error: Error): void {
        this.errorResponses.set(url, error);
    }

    public async get<T = unknown>(
        url: string,
        _params?: Record<string, unknown>,
    ): Promise<{ data: { status: string; data?: T } }> {
        if (this.getError(url)) {
            throw this.getError(url);
        }
        const response = this.getResponse(url);
        if (!response) {
            throw new Error(`No mock response for URL: ${url}`);
        }
        return response as { data: { status: string; data?: T } };
    }

    public async post<T = unknown>(
        url: string,
        _body?: Record<string, unknown>,
    ): Promise<{ data: { status: string; data?: T } }> {
        if (this.getError(url)) {
            throw this.getError(url);
        }
        const response = this.getResponse(url);
        if (!response) {
            throw new Error(`No mock response for URL: ${url}`);
        }
        return response as { data: { status: string; data?: T } };
    }

    public async put<T = unknown>(
        url: string,
        _body?: Record<string, unknown>,
    ): Promise<{ data: { status: string; data?: T } }> {
        if (this.getError(url)) {
            throw this.getError(url);
        }
        const response = this.getResponse(url);
        if (!response) {
            throw new Error(`No mock response for URL: ${url}`);
        }
        return response as { data: { status: string; data?: T } };
    }

    public async request<T = unknown>(
        url: string,
        _options: { method: string; body?: Record<string, unknown> },
    ): Promise<{ data: { status: string; data?: T } }> {
        if (this.getError(url)) {
            throw this.getError(url);
        }
        const response = this.getResponse(url);
        if (!response) {
            throw new Error(`No mock response for URL: ${url}`);
        }
        return response as { data: { status: string; data?: T } };
    }
}

